(function () {
  var frame = setPlotFrame({ xDomain: [0, 100], yDomain: [-100, 100], margin: 64 });
  var draw = frame.draw;

  // ---- background shading ----
  var pinkRect = draw.rect().fill('#f3dcd6').stroke('none');
  var greenRect = draw.rect().fill('#ddebd3').stroke('none');
  function layoutBg() {
    var x0 = plotX(0), x1 = plotX(100), yTop = plotY(100), y0 = plotY(0), yBot = plotY(-100);
    pinkRect.move(x0, yTop).size(x1 - x0, y0 - yTop);
    greenRect.move(x0, y0).size(x1 - x0, yBot - y0);
  }
  layoutBg();

  // ---- zero dashed line ----
  var zeroLine = draw.line().stroke({ color: '#8a8a8a', width: 1.6, dasharray: '7,5' });
  function layoutZero() {
    zeroLine.plot(plotX(0), plotY(0), plotX(100), plotY(0));
  }
  layoutZero();

  // ---- axes ----
  var yAxis = draw.line().stroke({ color: '#222', width: 2 });
  var xAxis = draw.line().stroke({ color: '#222', width: 2 });
  var tick0 = draw.line().stroke({ color: '#222', width: 2 });
  function layoutAxes() {
    yAxis.plot(plotX(0), plotY(100), plotX(0), plotY(-100));
    xAxis.plot(plotX(0), plotY(-100), plotX(100), plotY(-100));
    tick0.plot(plotX(0) - 7, plotY(0), plotX(0), plotY(0));
  }
  layoutAxes();

  // ---- static text ----
  function halo(t) {
    return t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  }
  var tFree = halo(draw.text('Free energy').font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill('#111'));
  var tXlab = halo(draw.text('Increasing temperature (K)').font({ size: 15, weight: 'bold', family: 'sans-serif' }).fill('#111'));
  var tGpos = halo(draw.text('ΔG > 0').font({ size: 13, family: 'sans-serif' }).fill('#111'));
  var tGneg = halo(draw.text('ΔG < 0').font({ size: 13, family: 'sans-serif' }).fill('#111'));
  var tZero = halo(draw.text('0').font({ size: 13, family: 'sans-serif' }).fill('#111'));
  var tNon = halo(draw.text('Nonspontaneous').font({ size: 16, family: 'sans-serif' }).fill('#111'));
  var tSpon = halo(draw.text('Spontaneous').font({ size: 16, family: 'sans-serif' }).fill('#111'));

  function layoutText() {
    tFree.move(14, (plotY(100) + plotY(-100)) / 2).rotate(-90, 14, (plotY(100) + plotY(-100)) / 2);
    tXlab.move((plotX(0) + plotX(100)) / 2, plotY(-100) + 26).attr({ 'text-anchor': 'middle' });
    tGpos.move(34, (plotY(100) + plotY(0)) / 2).rotate(-90, 34, (plotY(100) + plotY(0)) / 2);
    tGneg.move(34, (plotY(0) + plotY(-100)) / 2).rotate(-90, 34, (plotY(0) + plotY(-100)) / 2);
    tZero.move(plotX(0) - 22, plotY(0) - 7);
    tNon.move(plotX(78), plotY(58)).attr({ 'text-anchor': 'middle' });
    tSpon.move(plotX(78), plotY(-45)).attr({ 'text-anchor': 'middle' });
  }
  layoutText();

  // ---- four lines ----
  // dG = dH - T*dS  -> slope on plot = -dS
  // Asymmetric dH for yellow lines so crossing is slightly above zero
  var lines = [
    { id: 'red',  color: '#c0392b', dH: 40,  dS: -0.5,  lab1: 'ΔH > 0', lab2: 'ΔS < 0', key: 'ΔH > 0, ΔS < 0', tLab: 32 },
    { id: 'yd',   color: '#d4a017', dH: 40,  dS: 0.6,   lab1: 'ΔH > 0', lab2: 'ΔS > 0', key: 'ΔH > 0, ΔS > 0', tLab: 30 },
    { id: 'yu',   color: '#d4a017', dH: -30, dS: -0.6,  lab1: 'ΔH < 0', lab2: 'ΔS < 0', key: 'ΔH < 0, ΔS < 0', tLab: 30 },
    { id: 'grn',  color: '#6aa832', dH: -30, dS: 0.5,   lab1: 'ΔH < 0', lab2: 'ΔS > 0', key: 'ΔH < 0, ΔS > 0', tLab: 32 }
  ];
  lines.forEach(function (L) {
    L.fn = function (T) { return L.dH - T * L.dS; };
    L.handle = plotFunction(L.id, { fn: L.fn, domain: [0, 100], samples: 2, stroke: L.color, width: 3 });
    L.labelEls = [];
  });

  function screenAt(L, T) { return { x: plotX(T), y: plotY(L.fn(T)) }; }
  function lineAngle(L) {
    var a = screenAt(L, 10), b = screenAt(L, 90);
    return Math.atan2(b.y - a.y, b.x - a.x);
  }

  function buildLabels() {
    lines.forEach(function (L) {
      L.labelEls.forEach(function (e) { e.remove(); });
      L.labelEls = [];
      var ang = lineAngle(L);
      // Perpendicular "up" in screen coords: (sin(ang), -cos(ang))
      var nx = Math.sin(ang), ny = -Math.cos(ang);
      var p = screenAt(L, L.tLab);
      // ΔH label ABOVE the line (positive perp offset), ΔS BELOW (negative)
      var dH_offset = 18;
      var dS_offset = -18;
      var specs = [
        { text: L.lab1, offset: dH_offset },
        { text: L.lab2, offset: dS_offset }
      ];
      specs.forEach(function (s) {
        var cx = p.x + nx * s.offset, cy = p.y + ny * s.offset;
        var angDeg = ang * 180 / Math.PI;
        var t = halo(draw.text(s.text).font({ size: 13, family: 'sans-serif', style: 'italic' }).fill('#111'))
          .move(cx, cy - 6).attr({ 'text-anchor': 'middle' }).rotate(angDeg, cx, cy);
        L.labelEls.push(t);
      });
