        .fill(col).stroke({ color: '#fff', width: 2 });
    });
  }

  function applyVisibility() {
    lines.forEach(function (L) {
      var vis = isVisible(L);
      var bold = (selected !== 'All four' && vis);
      L.handle.node.opacity(vis ? 1 : 0.13);
      L.handle.node.find('polyline').stroke({ color: vis ? L.color : '#bbbbbb', width: bold ? 4.5 : 3 });
