    currentT = v;
    drawCursor();
  };
  window.update_signCombination = function (val) {
    selected = val;
    applyVisibility();
  };

  // ---- resize ----
  document.addEventListener('fig-resize', function () {
    layoutBg(); layoutZero(); layoutAxes(); layoutText();
    lines.forEach(function (L) { L.handle.sample(); });
    buildLabels();
    applyVisibility();
  });

  // ---- demo steps ----
  var steps = [
    { t: 'Four sign combinations', s: 'All four', temp: 15,
      n: 'At low temperature all four lines sit on the side set by their ΔH: the red (ΔH>0, ΔS<0) line is nonspontaneous and the green (ΔH<0, ΔS>0) line is spontaneous, and neither will ever cross zero because their slopes push them further away.' },
    { t: 'ΔH > 0, ΔS > 0: heat-driven spontaneity', s: 'ΔH > 0, ΔS > 0', temp: 30,
      n: 'Isolating this yellow line shows it starts in the pink (nonspontaneous) region because ΔH > 0 sets a positive intercept, but its negative slope (−ΔS < 0) carries it downward until it crosses ΔG = 0 — above that temperature the process becomes spontaneous.' },
    { t: 'ΔH < 0, ΔS < 0: cold-driven spontaneity', s: 'ΔH < 0, ΔS < 0', temp: 30,
      n: 'The other yellow line starts in the green (spontaneous) region because ΔH < 0, but its positive slope (−ΔS > 0) lifts it until it crosses ΔG = 0 — here raising the temperature destroys spontaneity, the mirror image of the previous case.' },
    { t: 'Sweep the temperature', s: 'All four', temp: 70,
      n: 'With all four lines shown, drag the temperature cursor from low to high: the red and green lines stay on their original sides, while the two yellow lines each flip shading exactly at their own ΔG = 0 crossing — the temperature at which ΔH = TΔS.' }
  ];
  var cur = 0;
  function renderStep(i) {
    cur = Math.max(0, Math.min(steps.length - 1, i));
    var st = steps[cur];
    document.getElementById('signCombinationInput').value = st.s;
    document.getElementById('temperatureInput').value = st.temp;
    document.getElementById('temperatureVal').value = st.temp;
    document.getElementById('demoNarration').textContent = st.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + ' / ' + steps.length;
    update_signCombination(st.s);
    update_temperature(st.temp);
  }
  window.nextStep = function () { renderStep(cur + 1); };
  window.prevStep = function () { renderStep(cur - 1); };

  applyVisibility();
  renderStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

